    """
    Greedy diff-cover builder.
    - Start with B = {0}
    - Repeatedly try adding a new non-negative integer (not yet in B)
      that yields the largest improvement in the consecutive difference coverage n.
    - Stop when no candidate improves n, or when we hit a practical limit (2000 elements).
    - Ensure 0 is present (it is in the start).
    """
    import itertools

    def compute_n(B):
        # Compute all positive differences
        S = set()
        b = sorted(B)
        for i in range(len(b)):
            for j in range(i+1, len(b)):
                S.add(b[j] - b[i])
        if not S:
            return 0
        # Find max n such that 1..n are all in S
        k = 1
        while k in S:
            k += 1
        return k - 1

    def score_of(B):
        n = compute_n(B)
        if n <= 0:
            return float('-inf')
        return - (len(B) ** 2) / n

    # Simple cap on candidate range to keep search fast
    MAX_CAND = 200  # can be adjusted
    B = {0}
    best_score = score_of(B)
    best_B = set(B)

    # Precompute a simple neighborhood: check candidates in 1..MAX_CAND
    candidates = list(range(1, MAX_CAND + 1))

    # Greedy loop: try to improve n by adding a single new element
    improved = True
    while improved and len(B) < 2000:
        improved = False
        current_n = compute_n(B)
        current_size = len(B)
        best_candidate = None
        best_candidate_n = current_n
        best_candidate_score = score_of(B)

        for x in candidates:
            if x in B:
                continue
            new_B = B | {x}
            new_n = compute_n(new_B)
            if new_n > current_n:
