                    best_candidate_n = new_n
                    best_candidate_score = new_score

        if best_candidate is not None:
            B.add(best_candidate)
            improved = True
            best_score = best_candidate_score
            best_B = set(B)
        else:
            # no single-element improvement found; attempt a small random-like sweep by wrapping
            # (kept deterministic for reproducibility)
            # Try next-untried candidates to see if a different choice helps later
            for x in candidates:
                if x in B:
                    continue
                new_B = B | {x}
                new_n = compute_n(new_B)
                if new_n > current_n:
                    B.add(x)
                    improved = True
                    break

    # Final safety: ensure 0 is present
    if 0 not in B:
        B.add(0)

    # Return as a sorted list
    return sorted(B)

