def compute_n(B):
    if not B:
        return 0
    B = sorted(set(B))
    diffs = set()
    for i in range(len(B)):
        for j in range(i+1, len(B)):
            diffs.add(B[j] - B[i])
    if 1 not in diffs:
        return 0
    n = 0
    while (n+1) in diffs:
        n += 1
    return n

def missing_diffs(B, upto=None):
    B = sorted(set(B))
    diffs = set()
    for i in range(len(B)):
        for j in range(i+1, len(B)):
            diffs.add(B[j] - B[i])
    upto = upto if upto is not None else max(diffs) if diffs else 0
    return [d for d in range(1, upto+1) if d not in diffs]

def evaluate_extension(B, v):
    nb = sorted(set(B) | {v})
    if 0 not in nb:
        return 0, nb
    n = compute_n(nb)
    if n <= 0:
        return -10.0, nb
    score = - (len(nb) ** 2) / n
    return score, nb

