    B = sorted(set([0, 1]))
    best_B = B[:]
    best_n = compute_n(best_B)
    best_score = - (len(best_B) ** 2) / max(1, best_n)

    # Precedence: try to extend by evaluating promising insertions
    def candidate_inserts(Bcur, limit=200):
